134	 * via {@link resolveCredential}) instead of the full credentials map.
135	 *
136	 * The token is written as the WHATWG URL username only (no password component)
137	 * since Personal Access Tokens are typically passed in the username field.
138	 * Special characters in the token are automatically percent-encoded by the
139	 * URL serialiser — no string concatenation is used.
140	 *
141	 * @param url   - The remote URL to modify.
142	 * @param token - The credential token to inject.
143	 * @returns The URL with the token injected, or the original URL unchanged for
144	 *   non-HTTPS or malformed URLs.
145	 */
146	export function injectCredentialToken(url: string, token: string): string {
147	    const host = extractHost(url);
148	    if (host === null) return url;
149	
150	    try {
151	        const parsed = new URL(url);
152	        parsed.username = token;
153	        parsed.password = '';
154	        return parsed.toString();
155	    } catch {
156	        return url;
157	    }
158	}
