165	 *
166	 * @param url - The URL to inspect.
167	 */
168	export function hasEmbeddedCredentials(url: string): boolean {
169	    if (!url) return false;
170	    try {
171	        const parsed = new URL(url);
172	        if (parsed.protocol !== 'https:') return false;
173	        return parsed.username !== '';
174	    } catch {
175	        return false;
